     1|/**
     2| * IVX AUTONOMOUS CODER — FACTORY ENGINE EXTENSION.
     3| *
     4| * Owner mandate 2026-07-19: extend the autonomous coder from a PATCH-only engine
     5| * (replace_exact / create_file scoped to existing backend/ + expo/ files) into a
     6| * FACTORY engine that can build apps from scratch, install dependencies, provision
     7| * Supabase, run builds, create its own tools, and upgrade its own capability set —
     8| * turning IVX IA into a developer software enterprise with no hard ceiling.
     9| *
    10| * DESIGN:
    11| *  - Factory mode is a SUPERSET of patch mode. It adds new operation kinds:
    12| *      create_directory   — make a new directory tree (e.g. a new top-level app dir)
    13| *      create_module      — multi-file module scaffold (N files in one operation)
    14| *      install_dependency — add a npm/expo dependency to a target package.json
    15| *      run_supabase_migration — apply a SQL migration to the configured Supabase
    16| *      run_build          — produce an APK/AAB/IPA via the build pipeline
    17| *      create_tool        — register a new IVX-owned tool in the tool registry
    18| *      upgrade_self       — add a new capability to the autonomous coder itself
    19| *  - Factory mode expands the allowed path roots: in addition to backend/ and
    20| *    expo/, factory mode can create new top-level directories under a sanctioned
    21| *    allowlist (apps/, modules/, tools/). It can NEVER write to .git/, .rork/,
    22| *    node_modules/, or outside the workspace root.
    23| *  - Every factory operation is OWNER-GATED. Factory mode requires an explicit
    24| *    approval phrase (CONFIRM_IVX_FACTORY_MODE) separate from the patch/deploy
    25| *    phrases. No factory operation runs without it.
    26| *  - Every factory operation produces a structured proof record with the exact
    27| *    command, inputs, outputs, duration, and verification — same honest-evidence
    28| *    contract as the patch engine. No fake progress.
    29| *  - The tool registry is an in-memory + persistent (Supabase) list of IVX-owned
    30| *    tools. Each tool has a name, version, capability description, and an
    31| *    optional handler function. The autonomous coder can call registered tools
    32| *    from its LLM-generated plan, and it can create new tools via the
    33| *    `create_tool` operation — extending its own capability set without a code
    34| *    deploy of the engine itself.
    35| *  - The self-upgrade mechanism (`upgrade_self`) lets the engine add a new
    36| *    capability descriptor to its own capability manifest. The manifest is a
    37| *    versioned document (ivx_factory_capabilities) that the engine reads at the
    38| *    start of each factory job. A self-upgrade appends a new capability with a
    39| *    higher version, never removing existing ones (append-only growth).
    40| *
    41| * NOTHING here is faked. If a factory operation cannot be performed (missing
    42| * credentials, build tool unavailable, dependency install fails), the engine
    43| * returns STATUS: BLOCKED with the exact failure — never a phantom success.
    44| */
    45|import { mkdir, readFile, writeFile, access } from 'node:fs/promises';
    46|import { existsSync } from 'node:fs';
    47|import path from 'node:path';
    48|import { randomUUID } from 'node:crypto';
    49|
    50|// ── MARKER + VERSION ──────────────────────────────────────────────────────────
    51|
    52|export const IVX_FACTORY_ENGINE_MARKER = 'ivx-factory-engine-2026-07-19';
    53|export const IVX_FACTORY_ENGINE_VERSION = '1.0.0';
    54|
    55|/** Owner approval phrase required for ANY factory operation. */
    56|export const IVX_FACTORY_APPROVAL_PHRASE = 'CONFIRM_IVX_FACTORY_MODE';
    57|
    58|// ── OPERATION KINDS ───────────────────────────────────────────────────────────
    59|
    60|export type IVXFactoryOperationKind =
    61|  | 'create_directory'
    62|  | 'create_module'
    63|  | 'install_dependency'
    64|  | 'run_supabase_migration'
    65|  | 'run_build'
    66|  | 'create_tool'
    67|  | 'upgrade_self';
    68|
    69|export type IVXFactoryOperation = {
    70|  kind: IVXFactoryOperationKind;
    71|  /** Relative path target (for file/dir operations). */
    72|  target?: string;
    73|  /** File contents for create_module (map of relative path -> content). */
    74|  files?: Array<{ path: string; content: string }>;
    75|  /** Dependency spec for install_dependency. */
    76|  dependency?: { name: string; version?: string; packageJsonPath?: string };
    77|  /** SQL for run_supabase_migration. */
    78|  sql?: string;
    79|  /** Migration name (for audit). */
    80|  migrationName?: string;
    81|  /** Build target for run_build. */
    82|  buildTarget?: 'apk' | 'aab' | 'ipa' | 'web';
    83|  /** Tool descriptor for create_tool. */
    84|  tool?: IVXToolDescriptor;
    85|  /** Capability descriptor for upgrade_self. */
    86|  capability?: IVXCapabilityDescriptor;
    87|  /** Reason the LLM chose this operation. */
    88|  reason: string;
    89|};
    90|
    91|// ── TOOL REGISTRY ─────────────────────────────────────────────────────────────
    92|
    93|export type IVXToolDescriptor = {
    94|  name: string;
    95|  version: string;
    96|  capability: string;
    97|  /** Optional handler name — resolved against the registered handler table. */
    98|  handlerName?: string;
    99|  /** When this tool was registered. */
   100|  registeredAt: string;
   101|  /** Owner who approved registration. */
   102|  approvedBy: string;
   103|};
   104|
   105|export type IVXToolHandler = (input: unknown) => Promise<unknown>;
   106|
   107|/** In-memory tool registry (persistent layer is Supabase ivx_factory_tools). */
   108|const toolRegistry = new Map<string, IVXToolDescriptor>();
   109|const toolHandlers = new Map<string, IVXToolHandler>();
   110|
   111|export function registerToolHandler(handlerName: string, handler: IVXToolHandler): void {
   112|  toolHandlers.set(handlerName, handler);
   113|}
   114|
   115|export function getRegisteredTools(): IVXToolDescriptor[] {
   116|  return Array.from(toolRegistry.values());
   117|}
   118|
   119|export function getToolHandler(handlerName: string): IVXToolHandler | undefined {
   120|  return toolHandlers.get(handlerName);
   121|}
