   127|  id: string;
   128|  /** Human-readable label. */
   129|  label: string;
   130|  /** Version of this capability (append-only — higher versions extend, never replace). */
   131|  version: string;
   132|  /** Operation kinds this capability enables. */
   133|  operations: IVXFactoryOperationKind[];
   134|  /** When this capability was added. */
   135|  addedAt: string;
   136|};
   137|
   138|/** The base capability manifest — what the factory engine ships with. */
   139|export const BASE_CAPABILITY_MANIFEST: IVXCapabilityDescriptor[] = [
   140|  {
