   198|/** Runtime capability manifest (append-only — self-upgrade appends, never removes). */
   199|const capabilityManifest: IVXCapabilityDescriptor[] = [...BASE_CAPABILITY_MANIFEST];
   200|
   201|export function getCapabilityManifest(): IVXCapabilityDescriptor[] {
   202|  return [...capabilityManifest];
