   209|// ── PATH GUARDS ───────────────────────────────────────────────────────────────
   210|
   211|/** Sanctioned top-level roots for factory-mode file creation. */
   212|const FACTORY_ALLOWED_ROOTS = new Set([
   213|  'backend',
   214|  'expo',
   215|  'apps',
   216|  'modules',
   217|  'tools',
   218|  'docs',
   219|]);
   220|
   221|/** Paths the factory engine can NEVER touch, regardless of mode. */
   222|const FACTORY_FORBIDDEN_SEGMENTS = new Set([
   223|  '.git',
   224|  '.rork',
   225|  'node_modules',
   226|  '.expo',
   227|  'dist',
   228|  'build',
   229|  'coverage',
   230|]);
   231|
   232|function assertSafeFactoryPath(targetPath: string): void {
   233|  if (!targetPath || typeof targetPath !== 'string') {
   234|    throw new Error('Factory path missing.');
   235|  }
   236|  if (targetPath.includes('..') || targetPath.startsWith('/')) {
   237|    throw new Error(`Unsafe factory path rejected: ${targetPath}`);
   238|  }
   239|  const topSegment = targetPath.split('/')[0] ?? '';
   240|  if (!FACTORY_ALLOWED_ROOTS.has(topSegment)) {
   241|    throw new Error(
   242|      `Factory path outside sanctioned roots: ${targetPath}. Allowed roots: ${Array.from(FACTORY_ALLOWED_ROOTS).join(', ')}.`,
   243|    );
   244|  }
   245|  for (const segment of targetPath.split('/')) {
   246|    if (FACTORY_FORBIDDEN_SEGMENTS.has(segment)) {
   247|      throw new Error(`Factory path enters forbidden segment: ${targetPath}`);
   248|    }
   249|  }
