   252|// ── PROOF RECORD ──────────────────────────────────────────────────────────────
   253|
   254|export type IVXFactoryOperationProof = {
   255|  operation: IVXFactoryOperationKind;
   256|  target?: string;
   257|  startedAt: string;
   258|  finishedAt: string;
   259|  durationMs: number;
   260|  ok: boolean;
   261|  /** Exact command or action that ran (for audit). */
   262|  action: string;
   263|  /** Output preview (stdout / result summary). */
   264|  outputPreview: string;
