   266|  error: string | null;
   267|};
   268|
   269|export type IVXFactoryJobProof = {
   270|  marker: typeof IVX_FACTORY_ENGINE_MARKER;
   271|  version: typeof IVX_FACTORY_ENGINE_VERSION;
   272|  taskId: string;
