   298|// ── OPERATION EXECUTORS ───────────────────────────────────────────────────────
   299|
   300|async function executeCreateDirectory(
   301|  op: IVXFactoryOperation,
   302|  projectRoot: string,
   303|): Promise<IVXFactoryOperationProof> {
   304|  const startedAt = new Date().toISOString();
   305|  const startMs = Date.now();
   306|  const target = op.target ?? '';
   307|  const action = `mkdir -p ${target}`;
   308|  try {
   309|    assertSafeFactoryPath(target);
   310|    const fullPath = path.join(projectRoot, target);
   311|    await mkdir(fullPath, { recursive: true });
   312|    return {
   313|      operation: 'create_directory',
   314|      target,
   315|      startedAt,
   316|      finishedAt: new Date().toISOString(),
   317|      durationMs: Date.now() - startMs,
   318|      ok: true,
   319|      action,
   320|      outputPreview: `Created directory ${target}`,
   321|      error: null,
   322|    };
   323|  } catch (error) {
   324|    return {
   325|      operation: 'create_directory',
   326|      target,
   327|      startedAt,
   328|      finishedAt: new Date().toISOString(),
   329|      durationMs: Date.now() - startMs,
   330|      ok: false,
   331|      action,
   332|      outputPreview: '',
   333|      error: error instanceof Error ? error.message : 'create_directory failed',
   334|    };
   335|  }
   336|}
   337|
   338|async function executeCreateModule(
   339|  op: IVXFactoryOperation,
   340|  projectRoot: string,
   341|): Promise<IVXFactoryOperationProof> {
   342|  const startedAt = new Date().toISOString();
   343|  const startMs = Date.now();
   344|  const files = op.files ?? [];
   345|  const action = `create_module ${files.length} files under ${op.target ?? '(mixed)'}`;
   346|  try {
   347|    if (files.length === 0) {
   348|      throw new Error('create_module requires at least one file.');
   349|    }
   350|    const written: string[] = [];
   351|    for (const file of files) {
   352|      assertSafeFactoryPath(file.path);
   353|      const fullPath = path.join(projectRoot, file.path);
   354|      await mkdir(path.dirname(fullPath), { recursive: true });
   355|      await writeFile(fullPath, file.content, 'utf8');
   356|      written.push(file.path);
   357|    }
   358|    return {
   359|      operation: 'create_module',
   360|      target: op.target,
   361|      startedAt,
   362|      finishedAt: new Date().toISOString(),
   363|      durationMs: Date.now() - startMs,
   364|      ok: true,
   365|      action,
   366|      outputPreview: `Wrote ${written.length} files: ${written.slice(0, 5).join(', ')}${written.length > 5 ? ' ...' : ''}`,
   367|      error: null,
   368|    };
   369|  } catch (error) {
   370|    return {
   371|      operation: 'create_module',
   372|      target: op.target,
   373|      startedAt,
   374|      finishedAt: new Date().toISOString(),
   375|      durationMs: Date.now() - startMs,
   376|      ok: false,
   377|      action,
   378|      outputPreview: '',
   379|      error: error instanceof Error ? error.message : 'create_module failed',
   380|    };
   381|  }
