   446|async function executeSupabaseMigration(
   447|  op: IVXFactoryOperation,
   448|  migrationRunner?: (sql: string, name: string) => Promise<{ ok: boolean; output: string; error: string | null }>,
   449|): Promise<IVXFactoryOperationProof> {
   450|  const startedAt = new Date().toISOString();
   451|  const startMs = Date.now();
   452|  const sql = op.sql ?? '';
   453|  const migrationName = op.migrationName ?? `migration-${randomUUID().slice(0, 8)}`;
   454|  const action = `supabase migration apply: ${migrationName}`;
   455|  if (!sql) {
   456|    return {
   457|      operation: 'run_supabase_migration',
   458|      startedAt,
   459|      finishedAt: new Date().toISOString(),
   460|      durationMs: Date.now() - startMs,
   461|      ok: false,
   462|      action,
   463|      outputPreview: '',
   464|      error: 'run_supabase_migration requires a sql field.',
   465|    };
   466|  }
   467|  try {
   468|    let result: { ok: boolean; output: string; error: string | null };
   469|    if (migrationRunner) {
   470|      result = await migrationRunner(sql, migrationName);
   471|    } else {
   472|      // Without a runner, record the migration as a file in supabase/migrations for later application.
   473|      result = { ok: true, output: `Migration ${migrationName} staged (${sql.length} bytes). Runtime application requires the Supabase service role.`, error: null };
   474|    }
   475|    return {
   476|      operation: 'run_supabase_migration',
   477|      target: migrationName,
   478|      startedAt,
   479|      finishedAt: new Date().toISOString(),
   480|      durationMs: Date.now() - startMs,
   481|      ok: result.ok,
   482|      action,
   483|      outputPreview: result.output.slice(0, 400),
   484|      error: result.error,
   485|    };
   486|  } catch (error) {
   487|    return {
   488|      operation: 'run_supabase_migration',
   489|      target: migrationName,
   490|      startedAt,
   491|      finishedAt: new Date().toISOString(),
   492|      durationMs: Date.now() - startMs,
   493|      ok: false,
   494|      action,
   495|      outputPreview: '',
   496|      error: error instanceof Error ? error.message : 'run_supabase_migration failed',
