   542|async function executeCreateTool(
   543|  op: IVXFactoryOperation,
   544|  ownerId: string,
   545|): Promise<IVXFactoryOperationProof> {
   546|  const startedAt = new Date().toISOString();
   547|  const startMs = Date.now();
   548|  const tool = op.tool;
   549|  if (!tool) {
   550|    return {
   551|      operation: 'create_tool',
   552|      startedAt,
   553|      finishedAt: new Date().toISOString(),
   554|      durationMs: Date.now() - startMs,
   555|      ok: false,
   556|      action: 'create_tool (no descriptor)',
   557|      outputPreview: '',
   558|      error: 'create_tool requires a tool descriptor.',
   559|    };
   560|  }
   561|  const action = `register tool ${tool.name}@${tool.version}`;
   562|  try {
   563|    if (toolRegistry.has(tool.name)) {
   564|      throw new Error(`Tool ${tool.name} is already registered.`);
   565|    }
   566|    const descriptor: IVXToolDescriptor = {
   567|      ...tool,
   568|      registeredAt: new Date().toISOString(),
   569|      approvedBy: ownerId,
   570|    };
   571|    toolRegistry.set(tool.name, descriptor);
   572|    return {
   573|      operation: 'create_tool',
   574|      target: tool.name,
