import { gzipSync } from 'node:zlib';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

const files = [
  {
    path: 'backend/services/ivx-autonomous-coder-factory-runners.ts',
    message: 'feat: real factory runners (Supabase migration + dependency + build + GitHub file persistence)',
  },
  {
    path: 'backend/services/ivx-senior-developer-worker.ts',
    message: 'feat: wire real factory runners into worker factory branch + commit factory files to GitHub',
  },
  {
    path: 'expo/app.config.ts',
    message: 'fix: app.config.ts versionCode 48 → 50 (match build.gradle for v1.4.18(50))',
  },
];

async function commitOne(filePath: string, message: string): Promise<void> {
  const fullPath = path.join('/home/user/rork-app', filePath);
  const content = readFileSync(fullPath);
  const gzipBase64 = gzipSync(content).toString('base64');
  console.log(`\n=== Committing ${filePath} (${content.length} bytes → ${gzipBase64.length} gzip-b64) ===`);
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${OWNER_TOKEN}`,
    },
    body: JSON.stringify({
      action: 'github_commit_file',
      input: {
        path: filePath,
        content: gzipBase64,
        contentEncoding: 'gzip-base64',
        message,
      },
      confirm: true,
      confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
    }),
  });
  const text = await res.text();
  console.log(`HTTP ${res.status}: ${text.slice(0, 500)}`);
}

async function main(): Promise<void> {
  for (const f of files) {
    await commitOne(f.path, f.message);
  }
  console.log('\n=== All 3 commits submitted ===');
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

