import { readFileSync } from 'node:fs';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

// Live end-to-end factory proof: create_module (real new file) + run_supabase_migration (real table).
// The real runners injected into the worker read SUPABASE_SERVICE_ROLE_KEY + GITHUB_TOKEN from
// the Render runtime env. This proves the factory engine can build modules from scratch AND
// provision Supabase — the two operations that needed real runners.
const runId = `e2e-${Date.now()}`;
const prompt = `factory: Use the IVX Factory Engine to execute a live end-to-end proof (run ${runId}):

(1) create_module: Create a new module file at path "backend/services/ivx-factory-e2e-proof.ts" with content:
export const IVX_FACTORY_E2E_PROOF_RUN_ID = '${runId}';
export const IVX_FACTORY_E2E_PROOF_TIMESTAMP = '${new Date().toISOString()}';
export const IVX_FACTORY_E2E_PROOF_CAPABILITY = 'end-to-end factory proof: real module + real Supabase migration';

(2) run_supabase_migration: Apply SQL migration named "ivx_factory_e2e_proof_${runId}" with SQL:
CREATE TABLE IF NOT EXISTS public.ivx_factory_e2e_proof (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());

Approval phrase: CONFIRM_IVX_FACTORY_MODE.`;

console.log('=== Submitting live end-to-end factory proof ===');
console.log('runId:', runId);
console.log('prompt length:', prompt.length);

const res = await fetch(`${API}/api/ivx/owner-ai`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${OWNER_TOKEN}`,
  },
  body: JSON.stringify({ message: prompt }),
});

const text = await res.text();
console.log(`\nHTTP ${res.status}:`);
console.log(text.slice(0, 4000));

// If we got a taskId, poll the worker job for the result
try {
  const data = JSON.parse(text);
  const execStatus = data.executionStatus;
  if (execStatus && execStatus.taskId) {
    console.log(`\n=== Polling worker job ${execStatus.taskId} ===`);
    let attempts = 0;
    while (attempts < 30) {
      attempts++;
      await new Promise((r) => setTimeout(r, 3000));
      const jobRes = await fetch(`${API}/api/ivx/senior-developer/worker/jobs/${execStatus.taskId}`, {
        headers: { Authorization: `Bearer ${OWNER_TOKEN}` },
      });
      const jobText = await jobRes.text();
      const job = JSON.parse(jobText);
      console.log(`poll ${attempts}: status=${job.status} stage=${job.stage} progress=${job.progressPercent}% detail=${(job.stageDetail || '').slice(0, 200)}`);
      if (job.status === 'completed' || job.status === 'failed' || job.status === 'blocked' || job.status === 'cancelled') {
        console.log('\n=== FINAL JOB RESULT ===');
        console.log(JSON.stringify(job.result || job, null, 2).slice(0, 4000));
        console.log('\n=== ANSWER ===');
        console.log((data.answer || '').slice(0, 2000));
        break;
      }
    }
  }
} catch (err) {
  console.log('polling error:', err.message);
}

