import { gzipSync } from 'node:zlib';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const OWNER_TOKEN = readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';

async function commitOne(filePath, message) {
  const fullPath = path.join('/home/user/rork-app', filePath);
  const content = readFileSync(fullPath);
  const gzipBase64 = gzipSync(content).toString('base64');
  console.log(`\n=== Committing ${filePath} (${content.length} bytes -> ${gzipBase64.length} gzip-b64) ===`);
  let attempt = 0;
  while (attempt < 5) {
    attempt++;
    const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_TOKEN}` },
      body: JSON.stringify({
        action: 'github_commit_file',
        input: { path: filePath, content: gzipBase64, contentEncoding: 'gzip-base64', message },
        confirm: true,
        confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
      }),
    });
    const text = await res.text();
    const is503 = text.includes('503') || text.includes('Service Unavailable');
    console.log(`attempt ${attempt} HTTP ${res.status}: ${text.slice(0, 300)}`);
    if (res.ok) { console.log('COMMIT OK'); return true; }
    if (is503 && attempt < 5) {
      const delay = 5000 * attempt;
      console.log(`GitHub 503 — retrying in ${delay/1000}s...`);
      await new Promise((r) => setTimeout(r, delay));
    } else { return false; }
  }
  return false;
}

async function main() {
  const ok = await commitOne('backend/services/ivx-autonomous-coder-factory-runners.ts', 'fix: real migration runner uses Supabase Management API /database/query with SUPABASE_ACCESS_TOKEN (pg/exec returned 404)');
  console.log('\n=== done, ok=' + ok + ' ===');
}

main().catch((err) => { console.error('FATAL:', err); process.exit(1); });

